def replace_specialchar(s):
    """
    Replace all occurrences of spaces, commas, or dots with a colon.

    Args:
        s (str): The input string containing special characters to be replaced.

    Returns:
        str: A new string with spaces, commas, and dots replaced by colons.
    """
    # Define the set of characters to replace
    chars_to_replace = {' ', ',', '.'}

    # Iterate through each character in the string
    result = []
    for char in s:
        if char in chars_to_replace:
            result.append(':')
        else:
            result.append(char)

    return ''.join(result)

# Example usage and assertion check
