def max_Product(arr):
    if not arr:
        return None

    # Initialize min1, min2 as the two smallest numbers seen so far
    # and max1, max2 as the two largest numbers seen so far.
    # We use float('-inf') and float('inf') for initialization to handle negative numbers correctly.
    min1 = float('inf')
    min2 = float('inf')
    max1 = float('-inf')
    max2 = float('-inf')

    for num in arr:
        # Update maximums
        if num > max1:
            max2 = max1
            max1 = num
        elif num > max2:
            max2 = num

        # Update minimums
        if num < min1:
            min2 = min1
            min1 = num
        elif num < min2:
            min2 = num

    # Calculate products of pairs with highest product
    # The highest product can come from two large positive numbers or two large negative numbers.
    product1 = max1 * max2
    product2 = min1 * min2

    if product1 > product2:
        return (max1, max2)
    else:
        return (min1, min2)

