def ascii_value(char):
    """
    Returns the ASCII value of a single character.

    Args:
        char (str): A single character string.

    Returns:
        int: The ASCII value of the character, or None if input is invalid.
    """
    if not isinstance(char, str) or len(char) != 1:
        return None

    try:
        return ord(char)
    except TypeError:
        return None

