        return 0.0

    product = 1
    for num in numbers:
        product *= num

    length = len(numbers)
    result = product / length

    return result

def remove_lowercase(s):
    """
    Removes all lowercase substrings from the given string.

    Args:
        s (str): The input string.

    Returns:
        str: A new string with all lowercase characters removed.
    """
    result = []
    for char in s:
        if not char.islower():
            result.append(char)
    return ''.join(result)

def check_Consecutive(lst):
    if not lst:
        return True

    # Sort the list to ensure we are checking consecutive order regardless of input order
    sorted_lst = sorted(lst)

    for i in range(1, len(sorted_lst)):
        if sorted_lst[i] != sorted_lst[i-1] + 1:
            return False

    return True

