def reverse_vowels(s: str) -> str:
    vowels = set(['a', 'e', 'i', 'o', 'u'])
    s_list = list(s.lower())
    left, right = 0, len(s_list) - 1

    while left < right:
        if s_list[left] not in vowels:
            left += 1
        elif s_list[right] not in vowels:
            right -= 1
        else:
            s_list[left], s_list[right] = s_list[right], s_list[left]
            left += 1
            right -= 1

    return "".join(s_list)

def return_sum(d):
    """
    Write function to find the sum of all items in the given dictionary.
    assert return_sum({'a': 100, 'b':200, 'c':300}) == 600
    """
    if not isinstance(d, dict):
        raise TypeError("Input must be a dictionary")

    total = 0
    for key, value in d.items():
        if not isinstance(value, (int, float)):
            raise TypeError(f"Value for key '{key}' must be a number, got {type(value).__name__}")
        total += value

    return total

def frequency_lists(data):
    """
    Counts the frequency of each element in a flattened list of lists.

    Args:
        data (list of list): A list containing multiple inner lists.

    Returns:
        dict: A dictionary where keys are elements from the input lists and values are their counts.
    """
    # Initialize an empty dictionary to store frequencies
    frequency_map = {}

    # Iterate through each inner list in the data
    for sublist in data:
        # Iterate through each element in the current sublist
        for element in sublist:
            # Increment the count for the element if it exists, otherwise initialize to 1
            if element in frequency_map:
                frequency_map[element] += 1
            else:
                frequency_map[element] = 1

    return frequency_map
